import math

def check_n(n):
    if math.gcd(n, 6) != 1:
        return False

    a_min = n // 3 + 1
    a_max = n // 2

    for a in range(a_min, a_max + 1):
        k = n - 2 * a
        if k == 0:
            continue
        if k < 0:
            return False

        if k-1 < 0 or k-1 > a-1:
            binom_val = 0
        else:
            binom_val = math.comb(a-1, k-1)

        if binom_val % k != 0:
            return False
    return True

valid_n = [n for n in range(2, 200) if check_n(n)]
print(len(valid_n))
